// provider CI: verify a recorded expectation against the live response
function verifyContract(expected, actual) {
  // expected: { status, body: { field: typeName } }
  if (actual.status != expected.status) return { ok: false };

  for (const field of Object.keys(expected.body)) {
    if (typeof actual.body[field] !== expected.body[field]) {
      return { ok: false };
    }
  }
  return { ok: true };   // extra fields in actual.body are allowed
}
